function cp(n){ if(n<0x10000) return String.fromCharCode(n); n-=0x10000; return String.fromCharCode(0xD800+(n>>10),0xDC00+(n&0x3FF)); }
function animate(env,el,p){
    var t=el.text,o="";
    for(var i=0;i<t.length;i++){ var c=t.charCodeAt(i);
        if(c>=65&&c<=90) o+=cp(119808+(c-65));
        else if(c>=97&&c<=122) o+=cp(119834+(c-97));
        else if(c>=48&&c<=57) o+=cp(120782+(c-48));
        else o+=t.charAt(i); }
     el.text=o; return el;
}
